import type { HTMLAttributes } from "react";
import { cx } from "../utils/cx";

export type Tone = "neutral" | "accent" | "success" | "warning" | "danger" | "muted" | "info";

export type BadgeProps = HTMLAttributes<HTMLSpanElement> & {
  /** Color carries meaning only: success = live, warning = expiring, muted = archived. */
  tone?: Tone;
  /** `soft` sits on the page; `overlay` sits on a photograph (blurred black behind). */
  appearance?: "soft" | "overlay" | "outline";
};

/** A small label: gallery state, plan, count. Server-compatible. */
export function Badge({ tone = "neutral", appearance = "soft", className, ...rest }: BadgeProps) {
  return <span {...rest} className={cx("hm-badge", className)} data-tone={tone} data-appearance={appearance} />;
}

export type StatusProps = HTMLAttributes<HTMLSpanElement> & { tone?: Tone };

/** A dot and a label ("Live", "Draft"). The label is always text, so status never depends on color. */
export function Status({ tone = "neutral", className, children, ...rest }: StatusProps) {
  return (
    <span {...rest} className={cx("hm-status", className)} data-tone={tone}>
      <span className="hm-status-dot" aria-hidden="true" />
      {children}
    </span>
  );
}
